param([Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop';$fdRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'));$fdOut=[IO.Path]::GetFullPath($OutputDirectory)
if([IO.Path]::GetDirectoryName($fdOut)-ne(Join-Path $fdRoot 'reports/m4-crt-fdiv')-or(Test-Path -LiteralPath $fdOut)){throw 'Fresh private boundary report required'}
$fdName=Split-Path $fdOut -Leaf;if($fdName-notmatch'^[a-z0-9-]+$'){throw 'Simple private output name'}
$fdBuilds=@{O0=(Join-Path $fdRoot "build/m4-fdiv-$fdName-O0");O2=(Join-Path $fdRoot "build/m4-fdiv-$fdName-O2")};foreach($fdP in $fdBuilds.Values){if(Test-Path -LiteralPath $fdP){throw 'Fresh boundary build directories required'}}
function Hash([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
$fdPrimary=Join-Path $fdRoot 'reports/m4-crt-fdiv/native-build-r3/build.json';$fdGate=Get-Content -Raw -LiteralPath $fdPrimary|ConvertFrom-Json;foreach($fdGroup in @('sources','tools','artifacts')){foreach($fdPair in $fdGate.$fdGroup.PSObject.Properties){if((Hash $fdPair.Name)-ne$fdPair.Value){throw 'Frozen registry dependency changed'}}}
$fdSources=[ordered]@{};foreach($fdFile in Get-ChildItem -LiteralPath $PSScriptRoot -Recurse -File){$fdSources[$fdFile.FullName]=Hash $fdFile.FullName};foreach($fdPair in $fdGate.sources.PSObject.Properties){$fdSources[$fdPair.Name]=$fdPair.Value}
New-Item -ItemType Directory -Path $fdOut|Out-Null;foreach($fdPair in $fdSources.GetEnumerator()){$fdCopy=Join-Path $fdOut ('sources/'+[IO.Path]::GetRelativePath($fdRoot,$fdPair.Key));New-Item -ItemType Directory -Force -Path (Split-Path $fdCopy -Parent)|Out-Null;Copy-Item -LiteralPath $fdPair.Key -Destination $fdCopy}
$fdLLVM=Join-Path $fdRoot 'local/tools/llvm-21.1.8/clang+llvm-21.1.8-x86_64-pc-windows-msvc/bin';$fdVS='C:/Program Files/Microsoft Visual Studio/18/Community';$fdCMake=Join-Path $fdVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/cmake.exe';$fdTools=[ordered]@{};$fdCommands=[Collections.Generic.List[object]]::new();$fdPassed=$false;$fdLibraries=[ordered]@{}
function Run([string]$p,[string[]]$a,[string]$log){$fdTools[$p]=Hash $p;$fdLog=Join-Path $fdOut $log;[IO.File]::WriteAllBytes($fdLog,[byte[]]::new(0));&$p @a 2>&1|Tee-Object -FilePath $fdLog|Out-Null;$fdCode=$LASTEXITCODE;$fdCommands.Add([ordered]@{program=$p;arguments=$a;exit_code=$fdCode;log=$fdLog;log_sha256=(Hash $fdLog)});if($fdCode-ne0){throw 'Required boundary invocation failed'}}
try{Import-Module (Join-Path $fdVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll');Enter-VsDevShell -VsInstallPath $fdVS -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64'|Out-Null
 Run (Join-Path $fdLLVM 'clang.exe') @('-c',(Join-Path $PSScriptRoot 'capture.s'),'-o',(Join-Path $fdOut 'capture.obj')) 'assembly.log'
 foreach($fdLevel in @('O0','O2')){$fdLibrary=Join-Path $fdRoot "build/m4-fdiv-native-build-r3-$fdLevel/fdiv_registry.lib";$fdLibraries[$fdLibrary]=Hash $fdLibrary;$fdFlags=if($fdLevel-eq'O0'){'/Od /DNDEBUG /showIncludes'}else{'/O2 /DNDEBUG /showIncludes'}
  Run $fdCMake @('-G','Ninja','-S',$PSScriptRoot,'-B',$fdBuilds[$fdLevel],'-DCMAKE_BUILD_TYPE=Release',"-DCMAKE_CXX_COMPILER=$fdLLVM/clang-cl.exe","-DCMAKE_CXX_FLAGS_RELEASE=$fdFlags","-DMW34_BOUNDARY_OBJECT=$fdOut/capture.obj","-DMW34_FDIV_LIBRARY=$fdLibrary") "configure-$fdLevel.log"
  Run $fdCMake @('--build',$fdBuilds[$fdLevel],'--verbose') "build-$fdLevel.log"
  Run (Join-Path $fdBuilds[$fdLevel] 'fdiv_boundary.exe') @((Join-Path $fdRoot 'MW3/Mech3.exe'),(Join-Path $fdRoot 'local/mw3-staged/Shared_DLLs/MSVCRT.DLL'),(Join-Path $fdRoot 'reports/m4-crt-fdiv/native-derived-r1/pack.bin'),(Join-Path $fdOut "boundary-$fdLevel.bin")) "tests-$fdLevel.log"
 }
 foreach($fdPair in $fdSources.GetEnumerator()){if((Hash $fdPair.Key)-ne$fdPair.Value){throw 'Boundary source changed during invocation'}};$fdPassed=$true
}catch{$_|Out-String|Set-Content -LiteralPath (Join-Path $fdOut 'failure.txt');throw}
finally{$fdArtifacts=[ordered]@{};foreach($fdDir in @($fdOut)+@($fdBuilds.Values)){if(Test-Path -LiteralPath $fdDir){foreach($fdFile in Get-ChildItem -LiteralPath $fdDir -Recurse -File){$fdArtifacts[$fdFile.FullName]=Hash $fdFile.FullName}}};[ordered]@{passed=$fdPassed;sources=$fdSources;tools=$fdTools;libraries=$fdLibraries;commands=$fdCommands;artifacts=$fdArtifacts;primary_build=$fdPrimary;primary_build_sha256=(Hash $fdPrimary);scope='Direct call-boundary x87/ENV/MXCSR and ABI nonvolatile SIMD only; volatile SIMD recorded without equality claim';original_execution=$false}|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $fdOut 'build.json')}
